import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Button, Form, Input, Row, Select, notification } from 'antd'

import { AddUserStyle } from './index.style'
import UserManagementActions from '../../../../redux/userManagement/action'
import loadingActions from '../../../../../redux/loading/actions'
import errorActions from '../../../../../redux/error/actions'
import { get, map } from 'lodash'

const { addUser, getGroupList, editUser } = UserManagementActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

const FormItem = Form.Item
const { Option } = Select

class AddUser extends Component {
  constructor(props) {
    super(props)
    this.state = {
      editUserData: undefined
    }
    this.formRef = React.createRef()
  }

  componentDidMount() {
    this.props.getGroupList()
    this.props.resetLoadingRedux(['ADD_USER', 'EDIT_USER'])
    this.props.resetErrorRedux(['ADD_USER', 'EDIT_USER'])
  }

  componentWillReceiveProps(nextProps) {
    const { addUserLoading, addUserError, addUserMessage,
      editUserLoading, editUserError, editUserMessage, editUserData } = nextProps
    if (addUserLoading === false) {
      notification[addUserError ? 'error' : 'success']({ message: addUserMessage })
      if (addUserError === false) {
        this.props.closeModal()
        this.formRef.current.resetFields()
      }
      this.props.resetLoadingRedux(['ADD_USER'])
      this.props.resetErrorRedux(['ADD_USER'])
    }

    if (editUserLoading === false) {
      notification[editUserError ? 'error' : 'success']({ message: editUserMessage })
      if (editUserError === false) {
        this.props.closeModal()
        this.formRef.current.resetFields()
      }
      this.props.resetLoadingRedux(['EDIT_USER'])
      this.props.resetErrorRedux(['EDIT_USER'])
    }

    if(this.state.editUserData !== editUserData) {
      this.setState({ editUserData })
      this.formRef.current.setFieldsValue({
        'name': get(editUserData, 'name', undefined),
        'email': get(editUserData, 'email', undefined),
        'phone': get(editUserData, 'phone'),
        'groups': map(get(editUserData, 'groups'), 'name')
      })
    }
  }

  handleSubmit = values => {
    const { editUserData } = this.props
    if (editUserData) {
      this.props.editUser({
        body: {
          ...values,
          user_id: get(editUserData, 'id')
        }
      })
    } else {
      this.props.addUser({
        body: {
          ...values
        }
      })
    }
  }

  handleCancel = () => {
    this.formRef.current.resetFields()
    this.props.closeModal()
  }

  render() {
    const { title, groupListLoading, editUserData = {}, groupList = [], addUserLoading, editUserLoading } = this.props
    const { name, email, phone, groups } = editUserData

    return (
      <AddUserStyle>
        <div className='modal-header'>
          {title}
        </div>
        <Form ref={this.formRef} layout='vertical' className='form-container' onFinish={this.handleSubmit}>
          <div className='form-item-container'>
            <label className='form-label'>Name</label>
            <FormItem name='name' initialValue={name} rules={[{ required: true, message: 'Name is required' }]}>
              <Input />
            </FormItem>
          </div>
          <div className='form-item-container'>
            <label className='form-label'>Email</label>
            <FormItem name='email' initialValue={get(editUserData, 'email')} rules={[{ required: true, message: 'Email is required' }]}>
              <Input type='email' disabled={email} />
            </FormItem>
          </div>
          <div className='form-item-container'>
            <label className='form-label'>Phone</label>
            <FormItem name='phone' initialValue={phone}>
              <Input type='number' />
            </FormItem>
          </div>
          <div className='form-item-container'>
            <label className='form-label'>Groups</label>
            <FormItem name='groups' initialValue={map(groups, 'name')} rules={[{ required: true, message: 'Group is required' }]}>
              <Select
                loading={!!groupListLoading}
                disabled={!!groupListLoading}
                mode='multiple'
              >
                {
                  groupList.map(group => <Option key={group} value={group}>{group}</Option>)
                }
              </Select>
            </FormItem>
          </div>
          <Row justify='end'>
            <Button
              type='danger'
              className='danger-button'
              loading={!!addUserLoading || !!editUserLoading}
              onClick={this.handleCancel}
            >
              Cancel
            </Button>
            <Button
              type='primary'
              htmlType='submit'
              loading={!!addUserLoading || !!editUserLoading}
            >
              Submit
            </Button>
          </Row>
        </Form>

      </AddUserStyle>
    )
  }
}

export default connect(state => ({
  groupList: state.UserManagement.groupList,
  groupListLoading: state.Loading.GET_GROUP_LIST,

  addUserLoading: state.Loading.ADD_USER,
  addUserError: state.Error.ADD_USER,
  addUserMessage: state.UserManagement.addUserMessage,

  editUserLoading: state.Loading.EDIT_USER,
  editUserError: state.Error.EDIT_USER,
  editUserMessage: state.UserManagement.editUserMessage
}), {
  addUser,
  editUser,
  getGroupList,
  resetLoadingRedux,
  resetErrorRedux
})(AddUser)
