import React, { Component } from 'react'

import { DisplayKeyValueStyle, DisplayValue } from './styledComponent.style'
import { Button } from 'antd'

class DisplayKeyValue extends Component {
  render() {
    const { dataKey, value, link , color} = this.props

    return (
      <DisplayKeyValueStyle span={6}>
        <div className='data-key'>{dataKey}</div>
        { value &&
          link
          ?
          <Button
          type='primary'
          href={value}
          target='_blank'
          >
              View File
            </Button>
            :
            <DisplayValue className='data-value' color={color}>{value}</DisplayValue>
        }
      </DisplayKeyValueStyle>
    )
  }
}

export default DisplayKeyValue
