import React, { Component } from 'react'
import { connect } from 'react-redux'
import moment from 'moment-timezone'
import { Button, Card, Modal, notification, Row, Table, Popconfirm } from 'antd'
import { get } from 'lodash'
import { EditOutlined, UserAddOutlined } from '@ant-design/icons'

import UserManagementActions from '../../../redux/userManagement/action'
import loadingActions from '../../../../redux/loading/actions'
import errorActions from '../../../../redux/error/actions'
import { UserManagementStyle } from './index.style'
import { Header } from '../../../../components/StyledComponents'
import AddUser from './AddUser'

const { getUserList, updateUserStatus } = UserManagementActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class UserManagement extends Component {
  state = {
    showAddUserModal: false,
    editUserData: undefined
  }

  componentDidMount() {
    this.props.getUserList()
    this.props.resetLoadingRedux(['UPDATE_USER_STATUS'])
    this.props.resetErrorRedux(['UPDATE_USER_STATUS'])
  }

  componentWillReceiveProps(nextProps) {
    const { updateUserStatusLoading, updateUserStatusError, updateUserStatusMessage } = nextProps
    if (updateUserStatusLoading === false) {
      notification[updateUserStatusError ? 'error' : 'success']({ message: updateUserStatusMessage })
      this.props.resetLoadingRedux(['UPDATE_USER_STATUS'])
      this.props.resetErrorRedux(['UPDATE_USER_STATUS'])
    }
  }

  handleUpdateStatus = userData => {
    const { is_active: isActive, id } = userData
    this.props.updateUserStatus({
      body: {
        user_id: id,
        activate: !isActive
      }
    })
  }

  render() {
    const { userList = [], userListLoading, updateUserStatusLoading } = this.props
    const { showAddUserModal, editUserData } = this.state
    const columns = [{
      title: 'Name',
      key: 'name',
      dataIndex: 'name'
    }, {
      title: 'Email',
      key: 'email',
      dataIndex: 'email'
    }, {
      title: 'Phone',
      key: 'phone',
      dataIndex: 'phone'
    }, {
      title: 'Last Login',
      key: 'last_login',
      dataIndex: 'last_login',
      render: value => value && moment(value).tz('Asia/Jakarta').format('lll')
    }, {
      title: 'Status',
      key: 'is_active',
      dataIndex: 'is_active',
      render: value => value ? 'Active' : 'Inactive'
    }, {
      title: 'Actions',
      key: 'actions',
      render: rowData => <Row>
        <Popconfirm
          title={`Are you sure to update user status?`}
          okText='YES'
          cancelText='NO'
          onConfirm={() => {
            this.handleUpdateStatus(rowData)
          }}
        >
          <div className="action">
            {get(rowData, 'is_active') ? 'Revoke' : 'Activate'}
          </div>
        </Popconfirm>
        {get(rowData, 'is_active') &&
          <div className="action status" onClick={() => this.setState({ showAddUserModal: true, editUserData: rowData })}>
            <EditOutlined />
          </div>
        }
      </Row>
    }]

    return (
      <UserManagementStyle>
        <Modal
          visible={showAddUserModal}
          footer={null}
          closable={false}
        >
          <AddUser
            title={editUserData ? 'Edit User' : 'Add User'}
            editUserData={editUserData}
            closeModal={() => this.setState({ showAddUserModal: false, editUserData: undefined })}
          />
        </Modal>
        <Card>
          <Row justify='space-between'>
            <Header content='USER MANAGEMENT' />
            <Button
              type='primary'
              icon={<UserAddOutlined />}
              className='add-user-button'
              onClick={() => this.setState({ showAddUserModal: true })}
            >
              Add User
            </Button>
          </Row>
          <Table
            dataSource={userList}
            columns={columns}
            loading={!!userListLoading || !!updateUserStatusLoading}
            rowKey='id'
          />
        </Card>
      </UserManagementStyle>
    )
  }
}

export default connect(state => ({
  userList: state.UserManagement.userList,
  userListLoading: state.Loading.GET_USER_LIST,

  updateUserStatusLoading: state.Loading.UPDATE_USER_STATUS,
  updateUserStatusError: state.Error.UPDATE_USER_STATUS,
  updateUserStatusMessage: state.UserManagement.updateUserStatusMessage
}), {
  getUserList,
  updateUserStatus,
  resetLoadingRedux,
  resetErrorRedux
})(UserManagement)
